using System.Collections.Concurrent;
using OrdersApi.Models;

namespace OrdersApi.Services;

public sealed class OrderService : IOrderService
{
    private readonly ConcurrentDictionary<int, OrderResponse> _orders = new();
    private int _nextId;

    public Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken cancellationToken)
    {
        IReadOnlyList<OrderResponse> result = _orders.Values.ToList();
        return Task.FromResult(result);
    }

    public Task<OrderResponse?> GetByIdAsync(int id, CancellationToken cancellationToken)
    {
        _orders.TryGetValue(id, out var order);
        return Task.FromResult(order);
    }

    public Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var id = Interlocked.Increment(ref _nextId);
        var order = new OrderResponse(id, request.CustomerId, request.PlacedAt, request.TotalAmount, request.Status);
        _orders[id] = order;
        return Task.FromResult(order);
    }
}

